  const m=S.mode;
  if((m==='drone'||m==='menu'||m==='view'||m==='photo')&&ptrs.size===2){ const [a,b]=[...ptrs.values()]; const d=Math.hypot(a.x-b.x,a.y-b.y); if(pinch0>0) orbit.r=m==='photo'?clamp(pinchR0*pinch0/d,1.5,600):clamp(pinchR0*pinch0/d,60,7000); return; }
