canvas.addEventListener('wheel',e=>{ e.preventDefault(); if(S.mode==='drone'||S.mode==='menu'||S.mode==='view'||S.mode==='photo'){ if(S.mode==='view'&&!VW.paused) viewPause(true); orbit.r=clamp(orbit.r*Math.exp(e.deltaY*0.0012),S.mode==='photo'?1.5:20,S.mode==='photo'?600:7000); orbit.auto=false; } else if(S.mode==='walk'){ camS.dist=clamp(camS.dist*Math.exp(e.deltaY*0.001),2.5,12); } },{passive:false});
const ray=new THREE.Raycaster(), ndc=new THREE.Vector2();
